package net.civeira.phylax.feature.identity.tenantloginprovider.domain.valueholder;

import java.util.Optional;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;

import net.civeira.phylax.common.value.validation.ConstraintFailList;
import net.civeira.phylax.feature.identity.tenantloginprovider.domain.TenantLoginProvider;
import net.civeira.phylax.feature.identity.tenantloginprovider.domain.valueobject.SamlIdpCertVO;

class SamlIdpCertValueHolderUnitTest {

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign plain values on the holder of saml idp cert of tenant login provider")
  void test_saml_idp_cert_value_holder_assign_plain_value() {
    Object holder = new Object();
    SamlIdpCertValueHolder<Object> value = new SamlIdpCertValueHolder<>(holder);
    Assertions.assertSame(holder, value.samlIdpCert("file_1"), "Setters must return the holder");
    Assertions.assertTrue(value.getSamlIdpCertValue().isPresent(),
        "The plain value must be stored");
    Assertions.assertEquals("file_1", value.getSamlIdpCert().orElse(null),
        "The plain value must be recovered");
    Assertions.assertSame(holder, value.samlIdpCertNull(), "Setters must return the holder");
    Assertions.assertTrue(value.getSamlIdpCertValue().isPresent(),
        "A null value object must be stored");
    Assertions.assertFalse(value.getSamlIdpCert().isPresent(),
        "A null value must not have content");
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign value objects on the holder of saml idp cert of tenant login provider")
  void test_saml_idp_cert_value_holder_assign_value_object() {
    Object holder = new Object();
    SamlIdpCertValueHolder<Object> value = new SamlIdpCertValueHolder<>(holder);
    SamlIdpCertVO vo = SamlIdpCertVO.from("file_1");
    Assertions.assertFalse(value.getSamlIdpCertValue().isPresent(), "A new holder must be empty");
    Assertions.assertSame(holder, value.samlIdpCert(vo), "Setters must return the holder");
    Assertions.assertSame(vo, value.getSamlIdpCertValue().orElseThrow());
    Assertions.assertSame(holder, value.samlIdpCert(Optional.empty()));
    Assertions.assertFalse(value.getSamlIdpCertValue().isPresent(),
        "An empty optional must clear the value");
    Assertions.assertSame(holder, value.samlIdpCert(Optional.of(vo)));
    Assertions.assertSame(vo, value.getSamlIdpCertValue().orElseThrow());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test read the value of the holder of saml idp cert of tenant login provider against the original")
  void test_saml_idp_cert_value_holder_read() {
    Object holder = new Object();
    SamlIdpCertValueHolder<Object> value = new SamlIdpCertValueHolder<>(holder);
    SamlIdpCertVO vo = SamlIdpCertVO.from("file_1");
    SamlIdpCertVO other = SamlIdpCertVO.from("file_1");
    TenantLoginProvider original = Mockito.mock(TenantLoginProvider.class);
    Mockito.when(original.getSamlIdpCertValue()).thenReturn(other);
    ConstraintFailList fails = new ConstraintFailList();
    Assertions.assertSame(other, value.readSamlIdpCert(Optional.of(original), fails),
        "Without value, the original must be used");
    Assertions.assertTrue(fails.isEmpty());
    Assertions.assertNotNull(value.readSamlIdpCert(Optional.empty(), fails),
        "Without value and original a null value is returned");
    Assertions.assertTrue(fails.isEmpty(), "An optional value is never reported as missing");
    value.samlIdpCert(vo);
    ConstraintFailList others = new ConstraintFailList();
    Assertions.assertSame(vo, value.readSamlIdpCert(Optional.of(original), others),
        "With value, the original is ignored");
    Assertions.assertSame(vo, value.readSamlIdpCert(Optional.empty(), others));
    Assertions.assertTrue(others.isEmpty());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test unset the value of the holder of saml idp cert of tenant login provider")
  void test_saml_idp_cert_value_holder_unset() {
    Object holder = new Object();
    SamlIdpCertValueHolder<Object> value = new SamlIdpCertValueHolder<>(holder);
    SamlIdpCertVO vo = SamlIdpCertVO.from("file_1");
    value.samlIdpCert(vo);
    Assertions.assertSame(holder, value.unsetSamlIdpCertIfMatches("samlIdpCert_other"));
    Assertions.assertTrue(value.getSamlIdpCertValue().isPresent(),
        "Other field name must keep the value");
    Assertions.assertSame(holder, value.unsetSamlIdpCertIfMatches("samlIdpCert"));
    Assertions.assertFalse(value.getSamlIdpCertValue().isPresent(),
        "The field name must clear the value");
    value.samlIdpCert(vo);
    Assertions.assertSame(holder, value.unsetSamlIdpCert());
    Assertions.assertFalse(value.getSamlIdpCertValue().isPresent(), "Unset must clear the value");
  }
}
